//
// The app's service worker (sw.js at the site's root, scope = the site).
//
// It keeps the app's code in the browser so that the app loads fast and
// offline, and so that a new deployment never replaces the code of an open
// session: like WhatsApp Web, a new version is downloaded in the background
// and used only once the user accepts "New version available - Reload"
// (web/shell/update.ts).
//
// - Every build has its own cache, `receiver-code-<build>`, filled from the
//   build's file list (path -> SHA-256, generated by renderer/build.mjs);
//   every file is checked against its digest before it is stored, so a
//   half-updated CDN can't mix versions. Core files are downloaded when the
//   worker installs; images, sounds, fonts and translations other than
//   English when the app first uses them.
// - The build being served is the "approved" one (stored in the cache
//   `receiver-meta`), not necessarily this worker's: a newer worker serves
//   the approved build's files until the page asks it to switch ('apply').
// - The Tor directory snapshot (transport/tor/) is data, not code: it is
//   refreshed daily without a new build, so it comes from the network when
//   possible and from the cache otherwise, and never prompts an update.
// - Anything else (check pages, other paths) goes to the network untouched.

import manifest from 'virtual:web-sw-manifest';

type Manifest = Readonly<{
  build: string;
  files: Readonly<Record<string, string>>;
  core: ReadonlyArray<string>;
}>;

type ExtendableEvent = Event & { waitUntil(promise: Promise<unknown>): void };
type FetchEvent = ExtendableEvent & {
  request: Request;
  respondWith(response: Promise<Response> | Response): void;
};
type MessageEventWithPorts = ExtendableEvent & {
  data: unknown;
  ports: ReadonlyArray<MessagePort>;
};
type ServiceWorkerScope = Omit<typeof globalThis, 'addEventListener'> & {
  registration: { scope: string };
  skipWaiting(): Promise<void>;
  clients: { claim(): Promise<void> };
  addEventListener(type: 'install' | 'activate', listener: (event: ExtendableEvent) => void): void;
  addEventListener(type: 'fetch', listener: (event: FetchEvent) => void): void;
  addEventListener(type: 'message', listener: (event: MessageEventWithPorts) => void): void;
};

const sw = globalThis as unknown as ServiceWorkerScope;
const BUILD = manifest.build;
const CODE_PREFIX = 'receiver-code-';
const META_CACHE = 'receiver-meta';
const DATA_CACHE = 'receiver-data';
const MANIFEST_PATH = '__manifest.json';
const APPROVED_KEY = 'approved-build';
const DATA_PREFIX = 'transport/tor/';
const DOWNLOAD_CONCURRENCY = 6;

const scopeUrl = new URL(sw.registration.scope);

function codeCache(build: string): string {
  return `${CODE_PREFIX}${build}`;
}

function metaUrl(key: string): string {
  return new URL(`__receiver/${key}`, scopeUrl).href;
}

function fileUrl(path: string): string {
  return new URL(path, scopeUrl).href;
}

async function sha256(buffer: ArrayBuffer): Promise<string> {
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', buffer));
  return Array.from(digest, b => b.toString(16).padStart(2, '0')).join('');
}

function log(message: string): void {
  // oxlint-disable-next-line no-console
  console.log(`service worker ${BUILD.slice(0, 12)}: ${message}`);
}

/** Downloads `path` and checks it against `digest`; the response to store. */
async function download(path: string, digest: string): Promise<Response> {
  // Revalidate with the server: a copy from the HTTP cache may be older.
  const response = await fetch(fileUrl(path), { cache: 'no-cache', credentials: 'same-origin' });
  if (!response.ok) {
    throw new Error(`${path}: HTTP ${response.status}`);
  }
  const body = await response.arrayBuffer();
  const actual = await sha256(body);
  if (actual !== digest) {
    throw new Error(`${path}: content does not match this build (the site is being updated?)`);
  }
  return new Response(body, { status: 200, headers: response.headers });
}

async function getApproved(): Promise<string | undefined> {
  const meta = await caches.open(META_CACHE);
  const entry = await meta.match(metaUrl(APPROVED_KEY));
  const build = entry ? (await entry.text()).trim() : undefined;
  if (build && (await caches.has(codeCache(build)))) {
    return build;
  }
  return undefined;
}

async function setApproved(build: string): Promise<void> {
  const meta = await caches.open(META_CACHE);
  await meta.put(metaUrl(APPROVED_KEY), new Response(build));
  approvedMemo = undefined;
}

async function isComplete(build: string): Promise<boolean> {
  const cache = await caches.open(codeCache(build));
  return (await cache.match(fileUrl(MANIFEST_PATH))) !== undefined;
}

async function install(): Promise<void> {
  const cache = await caches.open(codeCache(BUILD));
  const missing: Array<string> = [];
  for (const path of manifest.core) {
    // oxlint-disable-next-line no-await-in-loop
    if (!(await cache.match(fileUrl(path)))) {
      missing.push(path);
    }
  }
  const started = Date.now();
  let next = 0;
  const workers = Array.from({ length: DOWNLOAD_CONCURRENCY }, async () => {
    while (next < missing.length) {
      const path = missing[next] as string;
      next += 1;
      // oxlint-disable-next-line no-await-in-loop
      const response = await download(path, manifest.files[path] as string);
      // oxlint-disable-next-line no-await-in-loop
      await cache.put(fileUrl(path), response);
    }
  });
  await Promise.all(workers);
  // Written last: its presence marks the build's core files as complete.
  await cache.put(
    fileUrl(MANIFEST_PATH),
    new Response(JSON.stringify(manifest), { headers: { 'content-type': 'application/json' } })
  );
  if (!(await getApproved())) {
    // First installation: this build is the one the page runs.
    await setApproved(BUILD);
  }
  log(`installed (${missing.length} of ${manifest.core.length} core files downloaded in ${Date.now() - started} ms)`);
}

async function cleanUp(): Promise<void> {
  const approved = await getApproved();
  if (!approved) {
    await setApproved(BUILD);
  }
  const keep = new Set([codeCache(BUILD), codeCache(approved ?? BUILD)]);
  for (const name of await caches.keys()) {
    if (name.startsWith(CODE_PREFIX) && !keep.has(name)) {
      // oxlint-disable-next-line no-await-in-loop
      await caches.delete(name);
    }
  }
}

sw.addEventListener('install', event => {
  // Taking over at once is safe: what is served is decided by the approved
  // build, not by which worker runs.
  event.waitUntil(install().then(() => sw.skipWaiting()));
});

sw.addEventListener('activate', event => {
  event.waitUntil(cleanUp().then(() => sw.clients.claim()));
});

type Served = { build: string; files: Readonly<Record<string, string>> };
let approvedMemo: Promise<Served> | undefined;

async function loadServed(): Promise<Served> {
  const build = (await getApproved()) ?? BUILD;
  if (build === BUILD) {
    return { build, files: manifest.files };
  }
  const cache = await caches.open(codeCache(build));
  const entry = await cache.match(fileUrl(MANIFEST_PATH));
  if (!entry) {
    return { build: BUILD, files: manifest.files };
  }
  const served = (await entry.json()) as Manifest;
  return { build, files: served.files };
}

function served(): Promise<Served> {
  approvedMemo ??= loadServed().catch(error => {
    approvedMemo = undefined;
    throw error;
  });
  return approvedMemo;
}

async function fromCode(request: Request, path: string): Promise<Response> {
  const { build, files } = await served();
  const digest = files[path];
  if (digest === undefined) {
    // Not part of the app (check pages), or a file of a different build.
    return fetch(request);
  }
  const cache = await caches.open(codeCache(build));
  const cached = await cache.match(fileUrl(path));
  if (cached) {
    return cached;
  }
  // Not stored yet (a file used on demand, or the build is still being
  // downloaded): from the network, stored if it is this build's version.
  try {
    const response = await download(path, digest);
    await cache.put(fileUrl(path), response.clone());
    return response;
  } catch (error) {
    log(`${error instanceof Error ? error.message : String(error)}; served from the network as is`);
    return fetch(request);
  }
}

async function fromData(request: Request): Promise<Response> {
  const cache = await caches.open(DATA_CACHE);
  try {
    const response = await fetch(request, { cache: 'no-cache' });
    if (response.ok) {
      await cache.put(request.url, response.clone());
    }
    return response;
  } catch (error) {
    const cached = await cache.match(request.url);
    if (cached) {
      return cached;
    }
    throw error;
  }
}

sw.addEventListener('fetch', event => {
  const { request } = event;
  if (request.method !== 'GET') {
    return;
  }
  const url = new URL(request.url);
  if (url.origin !== scopeUrl.origin || !url.pathname.startsWith(scopeUrl.pathname)) {
    return;
  }
  let path = decodeURIComponent(url.pathname.slice(scopeUrl.pathname.length));
  if (request.mode === 'navigate' && (path === '' || path === 'index.html')) {
    path = 'index.html';
  } else if (path === '') {
    return;
  }
  if (path.startsWith(DATA_PREFIX)) {
    event.respondWith(fromData(request));
    return;
  }
  // If the caches fail (storage evicted mid-request, quota), the network.
  event.respondWith(fromCode(request, path).catch(() => fetch(request)));
});

type StatusReply = {
  build: string;
  approved: string;
  updateReady: boolean;
};

async function status(): Promise<StatusReply> {
  const approved = (await getApproved()) ?? BUILD;
  return {
    build: BUILD,
    approved,
    updateReady: approved !== BUILD && (await isComplete(BUILD)),
  };
}

/**
 * Stores files the page loaded before this worker controlled it (the first
 * visit), so that they too come from the cache next time and offline.
 */
async function remember(paths: ReadonlyArray<string>): Promise<StatusReply> {
  const { build, files } = await served();
  const cache = await caches.open(codeCache(build));
  for (const path of paths) {
    const digest = files[path];
    // oxlint-disable-next-line no-await-in-loop
    if (digest === undefined || (await cache.match(fileUrl(path)))) {
      continue;
    }
    try {
      // oxlint-disable-next-line no-await-in-loop
      await cache.put(fileUrl(path), await download(path, digest));
    } catch (error) {
      log(`not stored: ${error instanceof Error ? error.message : String(error)}`);
    }
  }
  return status();
}

async function apply(): Promise<StatusReply> {
  if (await isComplete(BUILD)) {
    await setApproved(BUILD);
    await cleanUp();
    log('now serving this build');
  }
  return status();
}

sw.addEventListener('message', event => {
  const data = event.data as { type?: unknown } | null;
  const [port] = event.ports;
  if (!port || !data) {
    return;
  }
  const reply = (promise: Promise<StatusReply>) =>
    event.waitUntil(
      promise.then(
        value => port.postMessage({ ok: true, value }),
        error => port.postMessage({ ok: false, error: String(error?.message ?? error) })
      )
    );
  if (data.type === 'status') {
    reply(status());
  } else if (data.type === 'apply') {
    reply(apply());
  } else if (data.type === 'remember' && Array.isArray((data as { paths?: unknown }).paths)) {
    reply(remember((data as { paths: Array<unknown> }).paths.filter((p): p is string => typeof p === 'string')));
  }
});
